//! Alternatives: Abdication's spectral Events as a stereo effect. Brief,
//! random bumps and holes in the spectrum of whatever comes in, landing on the
//! harmonics of the notes played (MIDI) or of Root. No editor: the host shows
//! the parameters.
//!
//! The sound is the Faust DSP in ../dsp, compiled to Rust (`dsp.rs`,
//! generated by tools/gen-rust.sh: don't edit it by hand).

mod faust;
pub mod notes;
pub mod played;

mod dsp {
    #![allow(warnings, clippy::all)]
    use faust_types::*;
    include!("dsp.rs");
}

use std::num::NonZeroU32;
use std::sync::Arc;

use faust_types::{FaustDsp, ParamIndex};
use nih_plug::prelude::*;

pub use dsp::AlternativesDsp;
use faust::Labels;
use notes::Source;
use played::{Played, MAX_NOTES};

// ---------------------------------------------------------------------------
// Parameters
// ---------------------------------------------------------------------------

fn float(name: &str, default: f32, min: f32, max: f32, unit: &'static str, digits: usize) -> FloatParam {
    FloatParam::new(name, default, FloatRange::Linear { min, max })
        .with_unit(unit)
        .with_value_to_string(formatters::v2s_f32_rounded(digits))
}

fn percent(name: &str, default: f32) -> FloatParam {
    FloatParam::new(name, default, FloatRange::Linear { min: 0.0, max: 1.0 })
        .with_unit(" %")
        .with_value_to_string(formatters::v2s_f32_percentage(0))
        .with_string_to_value(formatters::s2v_f32_percentage())
}

/// Everything the DSP is set from, as plain values (the parameters read into
/// it; tests build it directly). The defaults are Abdication's (Events at
/// 6 dB, where it had them off), and the parameters' defaults.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Settings {
    pub density: f32,
    pub depth: f32,
    pub life: f32,
    pub sharp: f32,
    pub slots: i32,
    pub reach: i32,
    pub walk: f32,
    pub drift: f32,
    pub cut: f32,
    pub hold: bool,
    pub mix: f32,
    pub output: f32,
}

impl Default for Settings {
    fn default() -> Self {
        Self { density: 0.8, depth: 6.0, life: 2.0, sharp: 1.0, slots: 6, reach: 64, walk: 0.6, drift: 0.275, cut: 3.33,
               hold: true, mix: 1.0, output: 0.0 }
    }
}

impl Settings {
    /// In CONTROLS' order, in the DSP's units.
    fn values(&self) -> [f32; CONTROLS.len()] {
        [self.density * 100.0, self.depth, self.life, self.sharp, self.slots as f32, self.reach as f32, self.walk,
         self.drift, self.cut, self.hold as u8 as f32, self.mix, self.output]
    }
}

#[derive(Params)]
pub struct AlternativesParams {
    /// Root, or the MIDI notes routed to the plugin (Root until one arrives).
    #[id = "source"]
    pub source: EnumParam<Source>,
    #[id = "root"]
    pub root: IntParam,
    /// Share of the time each slot is in a bump.
    #[id = "density"]
    pub density: FloatParam,
    /// A bump's height (a turned-over one cuts Cut times deeper).
    #[id = "depth"]
    pub depth: FloatParam,
    /// How long bumps last (1: about 400 ms low down, 40 ms at 9 kHz).
    #[id = "life"]
    pub life: FloatParam,
    /// Narrower bumps above 1: toward a vocoder at high Depth and Density.
    #[id = "sharp"]
    pub sharp: FloatParam,
    /// How many bumps can be under way at once.
    #[id = "slots"]
    pub slots: IntParam,
    /// The highest harmonic a bump starts on (they favour the low ones).
    #[id = "reach"]
    pub reach: IntParam,
    /// 0 a still bell; 1 wanders in gain and frequency, and can turn a bump over.
    #[id = "walk"]
    pub walk: FloatParam,
    /// How far Walk wanders by itself, every few seconds.
    #[id = "drift"]
    pub drift: FloatParam,
    /// How much deeper a turned-over bump cuts than it boosts.
    #[id = "cut"]
    pub cut: FloatParam,
    /// Hold the average level, so the bumps reshape rather than swell.
    #[id = "hold"]
    pub hold: BoolParam,
    #[id = "mix"]
    pub mix: FloatParam,
    #[id = "output"]
    pub output: FloatParam,
}

impl Default for AlternativesParams {
    fn default() -> Self {
        let d = Settings::default();
        Self {
            source: EnumParam::new("Source", Source::Midi),
            root: notes::root_param(48),
            density: percent("Density", d.density),
            depth: float("Depth", d.depth, 0.0, 18.0, " dB", 1),
            life: float("Life", d.life, 0.25, 4.0, "", 2),
            sharp: float("Sharp", d.sharp, 0.5, 4.0, "", 2),
            slots: IntParam::new("Slots", d.slots, IntRange::Linear { min: 1, max: 12 }),
            reach: IntParam::new("Reach", d.reach, IntRange::Linear { min: 1, max: 128 }),
            walk: percent("Walk", d.walk),
            drift: FloatParam::new("Drift", d.drift, FloatRange::Linear { min: 0.0, max: 0.5 })
                .with_unit(" %")
                .with_value_to_string(formatters::v2s_f32_percentage(0))
                .with_string_to_value(formatters::s2v_f32_percentage()),
            cut: float("Cut", d.cut, 1.0, 6.0, "x", 2),
            hold: BoolParam::new("Hold Level", d.hold),
            mix: percent("Mix", d.mix),
            output: float("Output", d.output, -24.0, 12.0, " dB", 1),
        }
    }
}

impl AlternativesParams {
    pub fn settings(&self) -> Settings {
        Settings {
            density: self.density.value(),
            depth: self.depth.value(),
            life: self.life.value(),
            sharp: self.sharp.value(),
            slots: self.slots.value(),
            reach: self.reach.value(),
            walk: self.walk.value(),
            drift: self.drift.value(),
            cut: self.cut.value(),
            hold: self.hold.value(),
            mix: self.mix.value(),
            output: self.output.value(),
        }
    }
}

// ---------------------------------------------------------------------------
// The DSP and its controls
// ---------------------------------------------------------------------------

/// The Faust DSP, with its controls found by label.
pub struct Voice {
    dsp: Box<AlternativesDsp>,
    seed: ParamIndex,
    notes: [ParamIndex; MAX_NOTES],
    count: ParamIndex,
    /// Each parameter's control, in `values`' order.
    controls: [ParamIndex; CONTROLS.len()],
}

/// The Faust controls the parameters set one to one.
const CONTROLS: [&str; 12] = ["density", "depth", "life", "sharp", "slots", "reach", "walk", "drift", "cut", "hold", "mix", "output"];

impl Voice {
    pub fn new(sample_rate: f32, seed: u32) -> Self {
        let labels = Labels::of::<AlternativesDsp>();
        let mut dsp = Box::new(AlternativesDsp::new());
        dsp.init(sample_rate as i32);
        let mut v = Self {
            dsp,
            seed: labels.get("seed"),
            notes: std::array::from_fn(|i| labels.get(&format!("note{i}"))),
            count: labels.get("count"),
            controls: CONTROLS.map(|c| labels.get(c)),
        };
        v.reseed(seed);
        v
    }

    /// A fresh start on its own random stream (read on the first sample).
    pub fn reseed(&mut self, seed: u32) {
        self.dsp.instance_clear();
        self.dsp.set_param(self.seed, (seed % 1_000_000) as f32);
    }

    pub fn set(&mut self, settings: &Settings, notes_hz: &[f32]) {
        for (c, v) in self.controls.iter().zip(settings.values()) {
            self.dsp.set_param(*c, v);
        }
        self.set_notes(notes_hz);
    }

    pub fn set_notes(&mut self, notes_hz: &[f32]) {
        let notes = &notes_hz[..notes_hz.len().min(MAX_NOTES)];
        for (i, slot) in self.notes.iter().enumerate() {
            // Unused ones repeat the first, though they're never picked.
            self.dsp.set_param(*slot, notes.get(i).or(notes.first()).copied().unwrap_or(130.81));
        }
        self.dsp.set_param(self.count, notes.len().max(1) as f32);
    }

    pub fn compute(&mut self, inputs: [&[f32]; 2], outputs: [&mut [f32]; 2]) {
        let [l, r] = outputs;
        self.dsp.compute(l.len() as i32, &inputs, &mut [l, r]);
    }
}

/// A seed for an instance: different each time one is made.
fn fresh_seed() -> u32 {
    let nanos = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_or(0, |d| d.subsec_nanos());
    nanos ^ (&nanos as *const u32 as usize as u32).rotate_left(13)
}

// ---------------------------------------------------------------------------
// The plugin
// ---------------------------------------------------------------------------

pub struct Alternatives {
    params: Arc<AlternativesParams>,
    voice: Option<Voice>,
    played: Played,
    /// The input, copied: Faust's compute reads and writes separate buffers.
    input: [Vec<f32>; 2],
}

impl Default for Alternatives {
    fn default() -> Self {
        Self { params: Arc::new(AlternativesParams::default()), voice: None, played: Played::default(),
               input: [Vec::new(), Vec::new()] }
    }
}

impl Plugin for Alternatives {
    const NAME: &'static str = "Alternatives";
    const VENDOR: &'static str = "Abdicant";
    const URL: &'static str = "";
    const EMAIL: &'static str = "";
    const VERSION: &'static str = env!("CARGO_PKG_VERSION");

    const AUDIO_IO_LAYOUTS: &'static [AudioIOLayout] = &[AudioIOLayout {
        main_input_channels: NonZeroU32::new(2),
        main_output_channels: NonZeroU32::new(2),
        ..AudioIOLayout::const_default()
    }];
    const MIDI_INPUT: MidiConfig = MidiConfig::Basic;

    type SysExMessage = ();
    type BackgroundTask = ();

    fn params(&self) -> Arc<dyn Params> {
        self.params.clone()
    }

    fn initialize(&mut self, _: &AudioIOLayout, config: &BufferConfig, _: &mut impl InitContext<Self>) -> bool {
        self.voice = Some(Voice::new(config.sample_rate, fresh_seed()));
        let n = config.max_buffer_size as usize;
        self.input = [vec![0.0; n], vec![0.0; n]];
        true
    }

    fn reset(&mut self) {
        self.played.clear();
        if let Some(v) = self.voice.as_mut() {
            v.reseed(fresh_seed());
        }
    }

    fn process(&mut self, buffer: &mut Buffer, _: &mut AuxiliaryBuffers, context: &mut impl ProcessContext<Self>) -> ProcessStatus {
        let Some(voice) = self.voice.as_mut() else { return ProcessStatus::Normal };
        while let Some(event) = context.next_event() {
            match event {
                NoteEvent::NoteOn { note, .. } => self.played.note_on(note),
                NoteEvent::NoteOff { note, .. } => self.played.note_off(note),
                _ => {}
            }
        }
        let p = &self.params;
        voice.set(&p.settings(), &self.played.hz(p.source.value(), p.root.value()));

        let n = buffer.samples();
        let channels = buffer.as_slice();
        if channels.len() < 2 || n > self.input[0].len() {
            return ProcessStatus::Normal;
        }
        for (copy, channel) in self.input.iter_mut().zip(channels.iter()) {
            copy[..n].copy_from_slice(&channel[..n]);
        }
        let (left, rest) = channels.split_at_mut(1);
        voice.compute([&self.input[0][..n], &self.input[1][..n]], [&mut left[0][..n], &mut rest[0][..n]]);
        ProcessStatus::Normal
    }
}

